style.css:
@-moz-document domain("youtube.com") {
/* ♡ Olivia Rodrigo */

/* pink colors */
:root {
  --my-pink: #f7c6d9;
  --my-light-pink: #fff0f6;
  --my-rose: #df8eae;
  --my-dark-pink: #a94f76;
}

/* Olivia GIF background */
html,
body,
ytd-app {
  background-color: #fce8f0 !important;
  background-image: url("https://i.pinimg.com/originals/e8/7b/b0/e87bb04995962eda0e65fe907d4f9c83.gif") !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
}

/* pink surfaces */
ytd-rich-grid-renderer,
ytd-two-column-browse-results-renderer,
#primary,
#secondary,
ytd-watch-flexy {
  background-color: rgba(255, 240, 246, 0.88) !important;
  border-radius: 16px !important;
}

/* pink buttons */
yt-button-shape button,
ytd-button-renderer button,
#subscribe-button button {
  background: var(--my-pink) !important;
  color: var(--my-dark-pink) !important;
  border-radius: 22px !important;
  border: 1px solid var(--my-rose) !important;
}

/* pink search bar */
#search,
#search-input {
  background: var(--my-light-pink) !important;
  border-color: var(--my-rose) !important;
  border-radius: 24px !important;
}

/* rounded thumbnails */
ytd-thumbnail,
yt-image img {
  border-radius: 14px !important;
}

/* golden wing cursor */
body,
button,
a,
input {
  cursor: url("data:image/png;base64,"), 2 14, auto !important;
}
}
